  "srHowTitle": "Как их определить",
  "srHowBody": "Поддержка — это уровень, где цена перестаёт падать и отскакивает: спрос превышает предложение.\nСопротивление — это уровень, где цена перестаёт расти и разворачивается: предложение превышает спрос.\nЧем больше отскоков или отказов накапливает уровень, тем он надёжнее.\nЕсли цена пробивает уровень с силой и объёмом, поддержка и сопротивление меняются ролями.",
  "srUseTitle": "Практическое применение",
  "srUseBody": "Искать покупки около поддержки, со стопом чуть ниже неё.\nФиксировать прибыль или продавать около сопротивления.\nТорговать пробой только после подтверждения, в идеале на ретесте уровня.",
