  "authTrustNoCard": "Начните бесплатно, без карты",
  "authTrustLangs": "10 языков",
  "tweezersBottomName": "Пинцет снизу",
  "tweezersBottomDesc": "Две подряд свечи с одинаковыми минимумами. Признак сильной поддержки и покупательского интереса на этом уровне цены.",
  "tweezersTopName": "Пинцет сверху",
  "tweezersTopDesc": "Две подряд свечи с одинаковыми максимумами. Признак сильного сопротивления и интереса продавцов на этом уровне цены.",
  "evTitle": "Трейдинг на основе доказательств",
  "evIntro": "Что на самом деле ДОКАЗАНО данными, а не обещаниями? Здесь собрано то, что показывают академические исследования, регуляторы и столетие данных фондов, банков и трейдинговых столов: сколько людей реально теряет, какие стратегии пережили десятилетия статистики и как профессионалы управляют риском. Красная нить — закон больших чисел: одна сделка — случайность; тысяча сделок — статистика.",
  "hzTitle": "Сессии и сезонность",
  "hzIntro": "В определённые часы и даты рынок СКЛОНЕН вести себя схоже из-за денежных потоков (открытия, данные, закрытия, экспирации). Это не жёсткие правила и не сигналы к покупке: это статистические тенденции, помогающие выбрать, КОГДА торговать, а когда отойти. Всё время — по Франкфурту / UTC+2 (сдвигается ±1 ч из-за перехода на летнее время).",
  "msTitle": "Структура рынка",
  "msIntro": "До любой фигуры цена — это последовательность максимумов и минимумов. Чтение СТРУКТУРЫ — растут ли эти максимумы и минимумы, падают или идут вбок — говорит о тренде и о том, кто контролирует. Это база, на которой держатся графические фигуры, SMC и почти всё остальное. Здесь вы учитесь её читать и замечать, когда она меняется.",
  "mcTitle": "Макро: цикл, ставки и ротация",
  "mcIntro": "Макроэкономический фон движет целыми рынками — сильнее любого отдельного графика. Процентные ставки, инфляция и рост задают прилив, который поднимает или топит все лодки. Дело не в предсказании, а в позиционировании: знать, в какой фазе цикла мы находимся и что в ней обычно работает.",
  "cvTitle": "Глубокая оценка компании",
  "cvIntro": "Фундаментальный анализ ищет, сколько компания действительно стоит, и сравнивает это с её ценой на бирже. Цена ≠ стоимость: отличная компания может быть плохой инвестицией, если переплатить, а посредственная — выгодной сделкой. Здесь вы учитесь читать её цифры и оценивать стоимость — за пределами 4 базовых коэффициентов.",
  "ofTitle": "Order flow / чтение ленты",
  "ofIntro": "Цена — это результат; order flow — причина. Здесь вы учитесь читать реальное давление покупок и продаж — кто агрессивен, где ликвидность, где её поглощают — вместо одной готовой свечи. Нужны данные уровня 2 и практика, но это оптика профессиональных внутридневных трейдеров.",
  "protoTitle": "Протокол перед торговлей",
  "protoIntro": "Три инструмента, чтобы превратить дисциплину в конкретные правила: ваши предохранители, фильтр входа и ментальная проверка. Используйте их в этом порядке перед каждой сессией и каждой сделкой.",
  "brkTitle": "Правила остановки (предохранители)",
  "brkIntro": "Заранее решите, сколько можете потерять, прежде чем закрыть платформу. Когда лимит срабатывает — на сегодня всё: без исключений, без 'ещё одной'.",
  "brkCapital": "Капитал счёта",
  "brkRisk": "Риск на сделку",
  "brkDaily": "Дневная остановка",
  "brkWeekly": "Недельная остановка",
  "brkConsec": "Убытков подряд",
  "brkTrades": "Макс. сделок/день",
  "brkRulebook": "Твой свод правил",
  "brkRuleR": "Вы рискуете {r} на сделку (1R).",
  "brkRuleDaily": "Если теряете {v} за день ({n}R) — стоп до завтра.",
