  "tviRoiLabel": "отдача за час",
  "tviTakeaway": "«Успех в трейдинге — это 10% стратегии, 30% управления деньгами и 60% психологии.» — приписывается Ван К. Тарпу. Каждый час, отданный вашему мышлению и риску, окупается куда больше, чем ещё один час поиска идеального индикатора.",
  "tviAction": "Что с этим делать: не бросайте анализ, но перебалансируйте. Осознанно вкладывайте время в то, что приносит больше всего: письменный план, жёсткие правила риска (1% на сделку), дневник для разбора эмоциональных ошибок и рутину, которая тормозит вас на эмоциях.",
  "tviDisclaimer": "Проценты влияния следуют классической разбивке Ван К. Тарпа (60/30/10); другие авторы (Даглас, Стинбарджер) дают похожие цифры (психология 60-80%). Проценты времени иллюстрируют типичное распределение, а не результат исследования.",
  "shTitle": "Начни здесь",
