  "cantidad_91e0e6": "Количество",
  "aiCoachIntro_91e0e7": "Нажмите {analyzeBold}, и Claude Sonnet 4.5 проанализирует вашу текущую стратегию: сильные стороны, риски, практичные улучшения и итоговый вердикт. Разработано как старший коуч по торговле волатильностью.",
  "aiCoachAnalyze_91e0e8": "Анализировать",
  "aiCoachAnalyzing_91e0e9": "Анализирую...",
  "aiCoachReanalyze_91e0ea": "Пере-анализировать",
  "aiCoachDisclaimer_91e0eb": "Анализ создан ИИ — не является финансовой консультацией. Всегда проверяйте самостоятельно.",
  "bullishBias_91e0ec": "БЫЧИЙ уклон: вы зарабатываете, если {symbol} растёт. Точка безубыточности на экспирации ~${be}.",
