  "neutralBias_91e0ee": "НЕЙТРАЛЬНЫЙ уклон: вы зарабатываете, если {symbol} остаётся в диапазоне. {berange}",
  "neutralBreakEvens_91e0ef": "Точки безубыточности ${be1} и ${be2}.",
  "thetaNegative_91e0f0": "Theta ОТРИЦАТЕЛЬНАЯ: вы платите премию, которая снижается каждый день. Движение должно произойти БЫСТРО, пока время не съело стоимость.",
  "thetaPositive_91e0f1": "Theta ПОЛОЖИТЕЛЬНАЯ: вы получаете премию. ВРЕМЯ РАБОТАЕТ НА ВАС — если цена не двигается, вы зарабатываете на ежедневном распаде.",
  "thetaNeutral_91e0f2": "Theta НЕЙТРАЛЬНАЯ: длинные и короткие позиции компенсируются. Движение цены важнее времени.",
  "unlimitedRiskUp_91e0f3": "НЕОГРАНИЧЕННЫЙ РИСК при росте. Требует высокой маржи и дисциплинированного стоп-лосса.",
  "unlimitedRiskDown_91e0f4": "НЕОГРАНИЧЕННЫЙ РИСК при падении. Требует высокой маржи и дисциплинированного стоп-лосса.",
  "maxLossDefined_91e0f5": "МАКСИМАЛЬНЫЙ убыток определён: ${amount}. Вы не можете потерять больше этой суммы при любом сценарии.",
  "assignPut_91e0f6": "Если {symbol} упадёт ниже ${strike} и вы удержите позицию, вам назначат 100 акций/контракт по цене страйка.",
  "assignCall_91e0f7": "Если {symbol} поднимется выше ${strike} и вы удержите позицию, вы поставите 100 акций/контракт (если покрытый short call) или покроете с убытком (если naked).",
  "ivHighLong_91e0f8": "ВЫСОКАЯ IV ({iv}%): вы платите дорогие премии. Обвал волатильности после earnings может привести к убытку, даже если направление угадано.",
  "ivHighShort_91e0f9": "ВЫСОКАЯ IV ({iv}%): вы получаете высокие премии. Благоприятная ситуация для продавцов волатильности.",
