  "smcTitle": "Smart Money / ICT",
  "optTitle": "Опционные стратегии",
  "optIntro": "Комбинирование коллов и путов позволяет строить позиции с ограниченным риском и зарабатывать не только на направлении, но и на волатильности и распаде времени. Используйте Калькулятор опционов, чтобы увидеть греки и диаграмму выплат каждой стратегии.",
  "smcIntro": "Подход 'smart money' (популяризированный ICT) пытается отслеживать следы институционального капитала: где накапливаются ордера, как охотятся за ликвидностью розницы и куда возвращается цена. Он дискреционный — используйте его как конфлюэнс, а не как волшебную систему.",
  "ichiIntro": "Японский «график равновесия с одного взгляда», созданный Гоити Хосодой. Пять линий и проецируемое «облако» одновременно показывают тренд, поддержку/сопротивление, импульс и сигналы входа — он создан, чтобы читать рынок с одного взгляда. Очень популярен на форексе и в крипте.",
  "ewTitle": "Теория волн Эллиотта",
  "ewIntro": "Ральф Эллиотт заметил, что психология толпы движет рынками через повторяющиеся волновые модели. Цена растёт в 5-волновой «движущей» последовательности по тренду, затем корректируется в 3-волновой последовательности против него. Одна и та же форма 5-3 повторяется на каждом масштабе — от минут до десятилетий.",
  "fundAnalTab": "Фундаментальный",
