  "mechIntro": "Понимание работы рынков, типов ордеров и выбора брокера",
  "basicsHeroTitle": "Основные концепции трейдинга",
  "basicsHeroDesc": "Прежде чем открыть первую сделку, нужно освоить пять концепций: Long, Short, Take Profit (TP), Stop Loss (SL) и размер позиции. Это фундаментальные блоки, на которых строится любая торговая стратегия, независимо от актива или таймфрейма.",
  "basicsLongLabel": "Long (Длинная)",
  "basicsShortLabel": "Short (Короткая)",
  "basicsWhenToOpen": "Когда открывать",
  "basicsWhenYouWin": "Вы зарабатываете когда",
  "basicsWhenYouLose": "Вы теряете когда",
  "basicsEntry": "ВХОД",
  "basicsImportant": "Важно:",
  "basicsLongTitle": "Long (Длинная позиция / Покупка)",
  "basicsLongBadge": "БЫЧЬЯ",
  "basicsLongDesc": "Длинная позиция — это ставка на рост цены. Вы покупаете актив по определённой цене и продаёте, когда цена вырастет, получая разницу в виде прибыли. Это самая естественная операция: «покупай дёшево, продавай дорого».",
  "basicsLongWhenDesc": "Бычий сигнал, пробой сопротивления, сильный уровень поддержки",
  "basicsLongWinDesc": "Цена поднимается выше вашей цены входа",
  "basicsLongLoseDesc": "Цена опускается ниже вашей цены входа",
  "basicsLongDiagramCaption": "Покупаете → цена растёт → зарабатываете",
  "basicsLongFormulaTitle": "Формула прибыли (Long)",
  "basicsLongFormula": "PnL = (Цена выхода − Цена входа) × Количество",
  "basicsLongFormulaExample": "Пример: Покупаете 1 BTC за $90.000 и продаёте за $95.000 → PnL = +$5.000",
  "basicsFaqLongTitle": "Часто задаваемые вопросы — Long",
  "basicsFaqLong1Q": "Что значит «быть в лонге»?",
  "basicsFaqLong1A": "Быть в лонге (long) означает, что вы купили актив в расчёте на рост его цены. Вы зарабатываете, когда цена растёт выше вашей цены входа. Это самая интуитивная операция: «покупай дёшево, продавай дорого».",
  "basicsFaqLong2Q": "Когда открывать long?",
  "basicsFaqLong2A": "Когда анализ указывает на вероятный рост цены: после пробоя сопротивления, на сильном уровне поддержки, при подтверждённом бычьем momentum или после появления бычьего паттерна на графике.",
  "basicsFaqLong3Q": "Могу ли я потерять больше вложенного в long без leverage?",
  "basicsFaqLong3A": "Нет. Без leverage максимальный убыток составляет 100% вложенного (если актив упадёт до 0). С leverage вас могут ликвидировать раньше, именно поэтому SL так важен.",
  "basicsShortTitle": "Short (Короткая позиция / Продажа)",
  "basicsShortBadge": "МЕДВЕЖЬЯ",
  "basicsShortDesc": "Короткая позиция — это ставка на снижение цены. Вы «занимаете» актив у брокера, продаёте его по текущей цене и выкупаете обратно дешевле, когда цена падает. Разница между ценой продажи и ценой покупки — ваша прибыль.",
  "basicsShortWarning": "В short убытки теоретически неограничены (цена может расти бесконечно). Всегда используйте Stop Loss.",
  "basicsShortWhenDesc": "Нисходящий тренд, пробой поддержки, медвежий паттерн",
  "basicsShortWinDesc": "Цена падает ниже вашей цены входа (продажи)",
  "basicsShortLoseDesc": "Цена растёт выше вашей цены входа",
  "basicsShortDiagramCaption": "Продаёте → цена падает → зарабатываете",
  "basicsShortFormulaTitle": "Формула прибыли (Short)",
  "basicsShortFormula": "PnL = (Цена входа − Цена выхода) × Количество",
  "basicsShortFormulaExample": "Пример: Продаёте 1 BTC за $90.000 и выкупаете за $85.000 → PnL = +$5.000",
  "basicsCompareTitle": "Long vs Short — Быстрое сравнение",
