  "basicsPosNote": "* Приблизительные значения для EUR/USD. Могут незначительно варьироваться в зависимости от брокера и валюты.",
  "basicsMicroTitle": "Микро lot (0.01)",
  "basicsMicroUnits": "1,000 units",
  "basicsMicroDesc": "Минимальная единица, доступная у большинства брокеров. Идеальна для обучения без риска уничтожения счёта. При 10 pip против вас вы теряете всего $1. Отлично подходит для тестирования стратегий на реальном рынке с минимальным риском.",
  "basicsMicroTip": "Используйте для проверки стратегий на реальном рынке с контролируемым риском.",
  "basicsMiniTitle": "Мини lot (0.1)",
  "basicsMiniUnits": "10,000 units",
  "basicsMiniDesc": "В 10 раз больше микро lot. Стандартный размер для растущих счетов. Позволяет диверсифицировать несколько одновременных позиций без излишней экспозиции.",
  "basicsMiniTip": "Идеальная отправная точка для трейдеров среднего уровня с $1.000–$10.000.",
  "basicsStdTitle": "Стандартный lot (1.0)",
  "basicsStdUnits": "100,000 units",
  "basicsStdDesc": "Эталонная единица рынка Forex. Каждый pip стоит $10 в EUR/USD. При SL в 50 pip вы рискуете $500 — для риска лишь 1-2% на сделку нужно минимум $25.000–$50.000.",
  "basicsStdWarning": "Не используйте стандартные lot с небольшими счетами: риск на сделку будет чрезмерным.",
  "basicsMacroTitle": "Макро / Большой (10+ lot)",
  "basicsMacroUnits": "1M+ units",
  "basicsMacroDesc": "Институциональная территория. Банки, фонды и хедж-фонды торгуют такими объёмами. При 100 lot каждый pip стоит $1.000. Такие позиции нередко сами двигают цену и создают уровни поддержки/сопротивления, которые мы видим на графике.",
  "basicsMacroInfo": "Понимание этих объёмов помогает осознать, почему цена уважает определённые уровни.",
  "basicsPosFormulaTitle": "Как рассчитать оптимальный размер позиции",
  "basicsPosFormulaLabel": "Универсальная формула",
  "basicsPosFormula": "Lots = (Капитал × %Риска) ÷ (Pips_SL × Pip_Value)",
  "basicsPosFormulaExLabel": "Practical example:",
  "basicsPosFormulaExDesc": "Capital: $5,000 | Risk: 1% | SL: 50 pips",
  "basicsPosFormulaExResult": "Lots = ($5,000 × 0.01) ÷ (50 × $1) = 1.0 mini lot",
  "basicsPosGuideTitle": "Quick guide by capital",
  "basicsPosGuideNote": "* Assuming SL of 100 pips in EUR/USD",
  "basicsPosWarningTitle": "Самая распространённая ошибка: слишком большой размер позиции",
  "basicsPosWarning": "Открыть 1 стандартный lot, потому что «движение кажется надёжным», при счёте в $2.000, означает, что SL в 20 pip (−$200) заставит вас потерять 10% капитала за одну сделку. Всегда рассчитывайте lot исходя из максимально допустимого риска (1-2%), а не наоборот.",
  "basicsFaqPosTitle": "Часто задаваемые вопросы — Размер позиции",
  "basicsFaqPos1Q": "Что такое lot в трейдинге?",
  "basicsFaqPos1A": "Lot — это стандартная единица измерения размера позиции на Forex и CFD. 1 стандартный lot равен 100.000 единицам базовой валюты. Эта стандартизация позволяет легко рассчитать стоимость pip и риск каждой сделки.",
  "basicsFaqPos2Q": "С какого размера lot начинать?",
  "basicsFaqPos2A": "Если ваш счёт меньше $1.000, начинайте с микро lot (0.01). При $1.000–$10.000 используйте мини lot (0.1). Стандартные lot требуют счёта от $10.000+ для разумного управления рисками (риск лишь 1-2% на сделку).",
  "basicsFaqPos3Q": "Как leverage влияет на размер позиции?",
  "basicsFaqPos3A": "Leverage позволяет контролировать стандартный lot (100.000 единиц) при значительно меньшем капитале. При 1:100 для 1 lot нужна маржа всего $1.000. Но leverage одинаково усиливает и прибыль, и убытки: 1 lot с leverage 1:100 в EUR/USD — это $10/pip дохода ИЛИ убытка.",
  "basicsFaqPos4Q": "Что такое стоимость pip и как её рассчитать?",
  "basicsFaqPos4A": "Pip — это минимальное движение цены (0.0001 в EUR/USD). Стоимость pip = (0.0001 × lot × 100.000) в котируемой валюте. В EUR/USD: 1 стандартный lot → $10/pip | 1 мини lot → $1/pip | 1 микро lot → $0.10/pip.",
  "basicsFaqPos5Q": "Почему институционалы используют большие lot?",
  "basicsFaqPos5A": "Инвестиционные фонды, банки и хедж-фонды оперируют сотнями миллионов долларов. При 100 стандартных lot (10 миллионов единиц) каждый pip стоит $1.000. В таком масштабе движение цены на несколько pip означает десятки тысяч в PnL. Именно поэтому их входы и выходы часто отображаются как уровни поддержки/сопротивления на графике.",
  "basicsSummaryTitle": "Итог: 5 концепций вместе",
  "basicsSummaryLongDesc": "Покупаете в расчёте на рост цены",
  "basicsSummaryShortDesc": "Продаёте в расчёте на падение цены",
  "basicsSummaryTpDesc": "Закрывает с прибылью при достижении цели",
  "basicsSummarySlDesc": "Закрывает с контролируемым убытком при ошибке",
  "basicsSummaryLotsTitle": "LOTS",
  "basicsSummaryLotsDesc": "Микро · Мини · Стандартный · Макро",
  "wyckoffTab": "Wyckoff Method",
  "wyckoffTitle": "Wyckoff Method",
  "wyckoffIntro": "The Wyckoff Method is a technical analysis framework developed by Richard Wyckoff in the early 20th century. It studies price, volume, and time to identify the manipulation cycles of large institutional operators (the Composite Operator) and trade in harmony with them.",
  "wyckoffPsName": "Preliminary Support (PS)",
