  "altChartTitle": "Alternative Chart Types",
  "altChartIntro": "Beyond standard candlestick charts, these alternative chart types filter noise, clarify trends, and reveal market structure in unique ways. Each solves a specific analytical problem.",
  "altChartStrengths": "Strengths",
