  "strat_when_no_upside_risk": "Нейтрально при высокой IV и без желания рисковать наверху",
  "strat_when_no_downside_risk": "Нейтрально при высокой IV и без желания рисковать внизу",
  "strat_when_range_debit": "Ожидаете широкий диапазон и предпочитаете заплатить дебет, а не продавать премию",
  "strat_when_pin": "Ожидаете, что цена «прилипнет» к страйку",
  "strat_when_bwb": "Хотите «бабочку» с кредитом, приняв риск только с одной стороны",
  "strat_when_xmas": "Хотите профиль «бабочки» дешевле и со смещением",
  "strat_when_ladder_short": "Только если готовы оставить один конец открытым ради большего кредита",
  "strat_when_ladder_long": "Ожидаете либо узкий диапазон, либо очень сильное движение, но не среднее",
  "strat_csp_desc": "Продажа пута с полным резервированием страйка наличными. Выплата как у короткого пута, но капитал заморожен иначе.",
  "strat_protective_put_desc": "Акции плюс купленный ниже пут: страховка с франшизой.",
  "strat_covered_put_desc": "Шорт по акциям плюс проданный пут. Приносит премию, пока цена не растёт.",
  "strat_covered_strangle_desc": "Акции плюс проданные вне денег колл и пут. Двойная премия и обязательства с обеих сторон.",
  "strat_ratio_call_write_desc": "Акции с двумя проданными коллами: один покрытый, один непокрытый.",
  "strat_ratio_put_write_desc": "Шорт по акциям с двумя проданными путами: один покрытый, один непокрытый.",
  "strat_stock_repair_desc": "На убыточной позиции: один купленный колл и два проданных выше, чтобы снизить точку безубыточности без новых денег.",
  "strat_call_calendar_desc": "Продать ближний колл и купить такой же дальний. Живёт за счёт того, что время быстрее уходит у короткой ноги.",
  "strat_put_calendar_desc": "Продать ближний пут и купить такой же пут с более дальней экспирацией.",
  "strat_call_diagonal_desc": "Календарь с разными страйками: более высокая короткая нога добавляет бычий уклон.",
  "strat_put_diagonal_desc": "Пут-календарь с разными страйками: более низкая короткая нога добавляет медвежий уклон.",
  "strat_double_calendar_desc": "Два календаря: пут ниже и колл выше. Прибыль, если цена окажется между ними.",
  "strat_double_diagonal_desc": "Двойной календарь с более дальними длинными ногами: расширяет зону прибыли ценой большего дебета.",
  "strat_jelly_roll_desc": "Разница двух синтетиков на одном страйке в двух экспирациях. Цена — чистая ставка и дивиденд.",
  "strat_pmcc_desc": "Глубоко в деньгах дальний колл заменяет акции, против него продаётся ближний колл. Covered call без покупки 100 акций.",
  "strat_zebra_desc": "Два купленных колла в деньгах против одного проданного: дельта около 100 без чистой временной стоимости.",
  "strat_risk_reversal_desc": "Финансирует купленный колл продажей пута. Бычий синтетик почти без затрат.",
  "strat_seagull_desc": "Risk reversal с ограничением сверху проданным коллом: дешевле в обмен на отказ от последнего участка.",
  "strat_big_lizard_desc": "Проданный стрэддл с купленным выше коллом: убирает риск наверху, оставляя только нижний.",
  "strat_reverse_jade_desc": "Проданный колл плюс проданный пут-спред: без риска снизу, с риском сверху.",
  "strat_long_call_condor_desc": "Четыре колла, задающие плато прибыли между двумя внутренними страйками.",
  "strat_long_put_condor_desc": "Тот же кондор, полностью построенный на путах.",
  "strat_long_put_butterfly_desc": "Пут-бабочка: максимум на центральном страйке, риск ограничен дебетом.",
  "strat_put_bwb_desc": "Пут-бабочка с одним более широким крылом. Обычно открывается с кредитом и переносит весь риск на одну сторону.",
  "strat_xmas_call_desc": "Асимметричная колл-бабочка 1-3-2: дешевле классической, зона прибыли смещена.",
  "strat_xmas_put_desc": "Пут-версия бабочки 1-3-2, смещённая вниз.",
  "strat_bull_call_ladder_desc": "Bull call spread с третьим проданным выше коллом. Дополнительный кредит открывает неограниченный риск сверху.",
  "strat_bear_call_ladder_desc": "Колл продан внизу, два куплены выше: теряет в диапазоне, выигрывает на сильном росте.",
  "strat_bull_put_ladder_desc": "Пут продан вверху, два куплены ниже: теряет в диапазоне, выигрывает на резком падении.",
  "strat_bear_put_ladder_desc": "Bear put spread с третьим проданным ниже путом. Дополнительный кредит открывает риск снизу.",
